std::string data = "Path/To/File.txt";
size_t pos = data.rfind('.');

// 1. Substr (Creates a deep copy of the substring)
if (pos != std::string::npos) {
    std::string extension_copy = data.substr(pos + 1);
}

// 2. String_view (Zero copy reference, C++17+)
std::string_view sv(data);
if (pos != std::string::npos) {
    // Reference original memory: fast and efficient
    std::string_view extension_view = sv.substr(pos + 1);
}

// Convert string_view back to string only when required
std::string final_copy(extension_view);
